function showModal(n){$(n).modal("show")}class Sidebar{collapseExpandSidebar(){$(".sidebarCollapse").on("click",function(){$("#sidebar").toggleClass("active")})}activeLink(){var n=location.pathname;$(".vertical-nav-menu li a").each(function(){var t=$(this);t.attr("href")===n&&t.addClass("active")})}detectAndroidDevice(){var n=navigator.userAgent||navigator.vendor||window.opera;/android/i.test(n)&&$(".inner-content").addClass("android-device")}}let sideBar=new Sidebar;sideBar.collapseExpandSidebar();sideBar.activeLink();sideBar.detectAndroidDevice();